def add(i,n,cat,desc,year,count,unit,scope,level,properties,paper,data,lic,version='Publication-linked release',precision='exact',caveats=(),extra=(),provider=None,evidence=None,provenance='computed',access='open'):
 s=[{'url':'https://doi.org/'+paper,'title':'Scientific Data primary data descriptor','evidence':evidence or desc+' '+scope,'verified_date':'2026-11-01'}]
 if provider:s.append({'url':provider,'title':'Primary repository release metadata','evidence':'Confirms public release files and stated dataset terms; response hashes are saved in provider receipts.','verified_date':'2026-11-01'})
 d=dict(id=i,name=n,category=cat,description=desc,year=year,count=count,count_display=('Not verified'if count is None else ('~'if precision=='approximate'else '>'if precision=='lower_bound'else'')+f'{count:,}')+' '+unit,count_unit=unit,count_scope=scope,count_precision=precision,structure_level=level,provenance=provenance,properties=properties,access=access,license=lic,version=version,links={'paper':'https://doi.org/'+paper,'data':data},sources=s,caveats=list(caveats),tags=['Scientific Data','survey:20261101'])
 if extra:d['additional_counts']=list(extra)
 R.append(d)
